package codec_test

import (
	"fmt"

	decimal "github.com/neal/zerojson/conformance/internal/testleaf"

	"github.com/neal/zerojson/conformance/codec"
)

// example_test.go holds the examples that need real leaf types
// (the custom decimal test leaf, google/uuid) and a generated codec, so they live
// in the conformance module rather than the dependency-free root package.
// EventLeg / RawHolder / EventLegDecoder are generated by zerojsongen (see
// types.go's go:generate directive).

// Example_basicMarshalUnmarshal is the everyday round trip: AppendZJSON to
// encode (append-style, so a reused buffer costs no allocation) and
// UnmarshalZJSON to decode.
func Example_basicMarshalUnmarshal() {
	leg := codec.EventLeg{
		Ratio: decimal.RequireFromString("2.5"),
		Label: "ALPHA",
		Mode:  codec.ModeUp,
	}

	enc, err := leg.AppendZJSON(nil)
	if err != nil {
		panic(err)
	}
	fmt.Println(string(enc))

	var got codec.EventLeg
	if err := got.UnmarshalZJSON(enc); err != nil {
		panic(err)
	}
	fmt.Println(got.Label, got.Ratio.String())
	// Output:
	// {"ratio":"2.5","label":"ALPHA","mode":"up"}
	// ALPHA 2.5
}

// Example_pooledDecodeLoop shows zero-allocation decoding for a leaf-only
// shape. DecodeBorrow aliases input strings; keep input unchanged for the
// result's lifetime. Later calls do not invalidate earlier results.
func Example_pooledDecodeLoop() {
	batch := [][]byte{
		[]byte(`{"ratio":"1","label":"ALPHA","mode":"up"}`),
		[]byte(`{"ratio":"2.5","label":"BETA","mode":"down"}`),
	}

	var d codec.EventLegDecoder
	for _, msg := range batch {
		var leg codec.EventLeg
		if err := d.DecodeBorrow(msg, &leg); err != nil {
			panic(err)
		}
		// Borrowed strings refer to msg, which remains unchanged here.
		fmt.Printf("%s=%s\n", leg.Label, leg.Ratio.String())
	}
	// Output:
	// ALPHA=1
	// BETA=2.5
}

// Example_projectionRawPassthrough decodes only the fields it declares and
// routes the rest through unparsed via zerojson.Raw: RawHolder captures the
// "set" value's exact bytes without materializing them, and re-encodes them
// verbatim — the routing/passthrough pattern.
func Example_projectionRawPassthrough() {
	wire := []byte(`{"table":"orders","set":{"id":7,"qty":[1,2,3]},"where":{"id":7}}`)

	var rh codec.RawHolder
	if err := rh.UnmarshalZJSON(wire); err != nil {
		panic(err)
	}
	fmt.Println(rh.Table)
	fmt.Println(string(rh.Set)) // captured verbatim, never parsed into a map

	out, err := rh.AppendZJSON(nil)
	if err != nil {
		panic(err)
	}
	fmt.Println(string(out))
	// Output:
	// orders
	// {"id":7,"qty":[1,2,3]}
	// {"table":"orders","set":{"id":7,"qty":[1,2,3]},"where":{"id":7}}
}
